import React from "react";
import { AbsoluteFill, Sequence, staticFile } from "remotion";
import { Audio } from "@remotion/media";
import { FPS } from "./clips";

/**
 * Voiceover generated by `npm run narrate -- <name>` (see scripts/narrate.mjs).
 * Audio and manifest live in footage/narration/<name>/, the Remotion public dir.
 */

export type NarrationScene = {
  id: string;
  /** Path under the public dir, for staticFile() */
  file: string;
  durationSec: number;
};

export type NarrationManifest = {
  name: string;
  scenes: NarrationScene[];
};

/** Pause between consecutive lines. */
export const NARRATION_GAP_SEC = 0.6;

export const loadNarration = async (
  name: string,
): Promise<NarrationManifest> => {
  const res = await fetch(staticFile(`narration/${name}/manifest.json`));
  if (!res.ok) {
    throw new Error(
      `No narration for "${name}" yet. Run: npm run narrate -- ${name}`,
    );
  }
  return res.json();
};

/** Back-to-back placement in frames, with NARRATION_GAP_SEC between lines. */
export const placeNarration = (manifest: NarrationManifest, fps = FPS) => {
  let from = 0;
  const placed = manifest.scenes.map((scene) => {
    const durationInFrames = Math.ceil(scene.durationSec * fps);
    const at = { scene, from, durationInFrames };
    from += durationInFrames + Math.round(NARRATION_GAP_SEC * fps);
    return at;
  });
  const last = placed[placed.length - 1];
  const totalFrames = last ? last.from + last.durationInFrames : 0;
  return { placed, totalFrames };
};

export const NarrationTrack: React.FC<{
  manifest: NarrationManifest;
  volume?: number;
}> = ({ manifest, volume = 1 }) => {
  const { placed } = placeNarration(manifest);
  return (
    <>
      {placed.map(({ scene, from, durationInFrames }) => (
        <Sequence
          key={scene.id}
          from={from}
          durationInFrames={durationInFrames}
          name={`VO: ${scene.id}`}
          layout="none"
        >
          <Audio src={staticFile(scene.file)} volume={volume} />
        </Sequence>
      ))}
    </>
  );
};

export type NarrationPreviewProps = {
  script: string;
  manifest?: NarrationManifest;
};

/** Plays a narration script over a blank frame, for auditioning takes in Studio. */
export const NarrationPreview: React.FC<NarrationPreviewProps> = ({
  manifest,
}) => (
  <AbsoluteFill style={{ backgroundColor: "#0d0e12" }}>
    {manifest ? <NarrationTrack manifest={manifest} /> : null}
  </AbsoluteFill>
);
